def _free_code(code: str, taken: set[str]) -> str:
    """The code itself, or the next free one after it (an organization may have used it already)."""
    prefix, number = code.split("-")
    return next(f"{prefix}-{n}" for n in range(int(number), int(number) + 100) if f"{prefix}-{n}" not in taken)


def add_accounts(apps, schema_editor):
    Account = apps.get_model("ledger", "Account")
    JournalLine = apps.get_model("ledger", "JournalLine")
    Organization = apps.get_model("tenants", "Organization")
    for organization in Organization.objects.all():
        accounts = Account.objects.filter(organization=organization)
        taken = set(accounts.values_list("code", flat=True))
        names = {name.lower() for name in accounts.values_list("name", flat=True)}
        roles = set(accounts.exclude(system_role=None).values_list("system_role", flat=True))
        wanted = NEW + (PT if organization.legal_form in ("pt", "pt_perorangan") else [])
        for code, name, category, role, contra in wanted:
            if name.lower() in names or (role and role in roles):
                continue
            code = _free_code(code, taken)
            taken.add(code)
            Account.objects.create(organization=organization, code=code, name=name, category=category, system_role=role, is_contra=contra)
        for interest in accounts.filter(name="Beban Bunga", category="other_expense"):
            if not JournalLine.objects.filter(account=interest).exists():
                interest.category = "finance_cost"
                interest.save(update_fields=["category"])


